package com.falconenergy.controller;
import com.falconenergy.dto.*; import com.falconenergy.service.TransportPriceRangeService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping({"/api/v1/transport-price-ranges","/api/transport-price-ranges"}) @RequiredArgsConstructor @PreAuthorize("hasRole('FINANCE')") public class TransportPriceRangeController {private final TransportPriceRangeService service;@GetMapping public ResponseEntity<ApiResponse<List<TransportPriceRangeResponse>>> all(){return ResponseEntity.ok(ApiResponse.success("Transport price ranges retrieved",service.all()));}@PostMapping public ResponseEntity<ApiResponse<TransportPriceRangeResponse>> create(@Valid @RequestBody TransportPriceRangeRequest r){return ResponseEntity.ok(ApiResponse.success("Transport price range created",service.create(r)));}@PutMapping("/{id}") public ResponseEntity<ApiResponse<TransportPriceRangeResponse>> update(@PathVariable Long id,@Valid @RequestBody TransportPriceRangeRequest r){return ResponseEntity.ok(ApiResponse.success("Transport price range updated",service.update(id,r)));}@PatchMapping("/{id}/status") public ResponseEntity<ApiResponse<TransportPriceRangeResponse>> toggle(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success("Transport price range updated",service.toggle(id)));}@DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.ok(ApiResponse.success("Transport price range deleted"));}}
